31	abstract class AbstractConnectionProperty<V, T>
32	        implements ConnectionProperty<V, T>
33	{
34	    private final PropertyName propertyName;
35	    private final String key;
36	    private final Optional<T> defaultValue;
37	    private final Predicate<Properties> isRequired;
38	    private final Validator<Properties> validator;
39	    private final Converter<V, T> converter;
40	    private final String[] choices;
41	
42	    protected AbstractConnectionProperty(
43	            PropertyName propertyName,
44	            Optional<T> defaultValue,
45	            Predicate<Properties> isRequired,
46	            Validator<Properties> validator,
47	            Converter<V, T> converter)
48	    {
49	        this.propertyName = requireNonNull(propertyName, "key is null");
50	        this.key = propertyName.toString();
51	        this.defaultValue = requireNonNull(defaultValue, "defaultValue is null");
52	        this.isRequired = requireNonNull(isRequired, "isRequired is null");
53	        this.validator = requireNonNull(validator, "validator is null");
54	        this.converter = requireNonNull(converter, "converter is null");
55	
56	        Class<? super T> type = new TypeToken<T>(getClass()) {}.getRawType();
57	        if (type == Boolean.class) {
58	            choices = new String[] {"true", "false"};
59	        }
60	        else if (Enum.class.isAssignableFrom(type)) {
61	            choices = Stream.of(type.getEnumConstants())
62	                    .map(Object::toString)
63	                    .toArray(String[]::new);
64	        }
65	        else {
66	            choices = null;
67	        }
68	    }
69	
70	    protected AbstractConnectionProperty(
71	            PropertyName key,
72	            Predicate<Properties> required,
73	            Validator<Properties> allowed,
74	            Converter<V, T> converter)
75	    {
76	        this(key, Optional.empty(), required, allowed, converter);
77	    }
78	
79	    @Override
80	    public PropertyName getPropertyName()
81	    {
82	        return propertyName;
83	    }
84	
85	    @Override
86	    public DriverPropertyInfo getDriverPropertyInfo(Properties mergedProperties)
87	    {
88	        String currentValue = mergedProperties.getProperty(key);
89	        DriverPropertyInfo result = new DriverPropertyInfo(key, currentValue);
90	        result.required = isRequired.test(mergedProperties);
91	        result.choices = (choices != null) ? choices.clone() : null;
92	        return result;
93	    }
94	
95	    @Override
96	    public boolean isRequired(Properties properties)
97	    {
98	        return isRequired.test(properties);
99	    }
100	
101	    @Override
102	    public boolean isValid(Properties properties)
103	    {
104	        return !validator.validate(properties).isPresent();
105	    }
106	
107	    @Override
108	    public Optional<T> getValue(Properties properties)
109	            throws SQLException
110	    {
111	        return getValueOrDefault(properties, defaultValue);
112	    }
113	
114	    @Override
115	    public Optional<T> getValueOrDefault(Properties properties, Optional<T> defaultValue)
116	            throws SQLException
117	    {
118	        V value = (V) properties.get(key);
119	        if (value == null) {
120	            if (isRequired(properties) && !defaultValue.isPresent()) {
121	                throw new SQLException(format("Connection property %s is required", key));
122	            }
123	            return defaultValue;
124	        }
125	
126	        try {
127	            return Optional.of(converter.convert(value));
128	        }
129	        catch (RuntimeException e) {
130	            if (isEmpty(value)) {
131	                throw new SQLException(format("Connection property %s value is empty", key), e);
132	            }
133	            throw new SQLException(format("Connection property %s value is invalid: %s", key, value), e);
134	        }
135	    }
136	
137	    private boolean isEmpty(V value)
138	    {
139	        if (value instanceof String) {
140	            return ((String) value).isEmpty();
141	        }
142	        return false;
143	    }
144	
145	    @Override
146	    public void validate(Properties properties)
147	            throws SQLException
148	    {
149	        if (properties.containsKey(key)) {
150	            Optional<String> message = validator.validate(properties);
151	            if (message.isPresent()) {
152	                throw new SQLException(message.get());
153	            }
154	        }
155	
156	        getValue(properties);
157	    }
158	
159	    protected static final Predicate<Properties> NOT_REQUIRED = properties -> false;
160	
161	    protected static final Validator<Properties> ALLOWED = properties -> Optional.empty();
162	
163	    interface Converter<V, T>
164	    {
165	        T convert(V value);
166	    }
167	
