174	
175	    protected static final Converter<String, File> FILE_CONVERTER = File::new;
176	
177	    protected static final Converter<String, Boolean> BOOLEAN_CONVERTER = value -> {
178	        switch (value.toLowerCase(ENGLISH)) {
179	            case "true":
