183	        }
184	        throw new IllegalArgumentException("value must be 'true' or 'false'");
185	    };
186	
187	    protected interface Validator<T>
188	    {
189	        /**
190	         * @param value Value to validate
191	         * @return An error message if the value is invalid or empty otherwise
192	         */
193	        Optional<String> validate(T value);
194	
195	        default Validator<T> and(Validator<? super T> other)
196	        {
197	            requireNonNull(other, "other is null");
198	            // return the first non-empty optional
199	            return t -> {
200	                Optional<String> result = validate(t);
201	                if (result.isPresent()) {
202	                    return result;
203	                }
204	                return other.validate(t);
205	            };
206	        }
207	    }
208	
209	    protected static <T> Validator<T> validator(Predicate<T> predicate, String errorMessage)
210	    {
211	        requireNonNull(predicate, "predicate is null");
212	        requireNonNull(errorMessage, "errorMessage is null");
213	        return value -> {
214	            if (predicate.test(value)) {
215	                return Optional.empty();
216	            }
217	            return Optional.of(errorMessage);
218	        };
219	    }
