31	import static java.util.Objects.requireNonNull;
32	import static java.util.concurrent.TimeUnit.SECONDS;
33	
34	public class QueryRunner
35	        implements Closeable
36	{
37	    private final AtomicReference<ClientSession> session;
38	    private final boolean debug;
39	    private final OkHttpClient httpClient;
40	    private final Consumer<OkHttpClient.Builder> sslSetup;
41	
42	    public QueryRunner(
43	            TrinoUri uri,
44	            ClientSession session,
45	            boolean debug,
46	            HttpLoggingInterceptor.Level networkLogging)
47	    {
48	        this.session = new AtomicReference<>(requireNonNull(session, "session is null"));
49	        this.debug = debug;
50	
51	        OkHttpClient.Builder builder = new OkHttpClient.Builder();
52	        try {
53	            sslSetup = uri.getSetupSsl();
54	            uri.setupClient(builder);
55	        }
56	        catch (SQLException e) {
57	            throw new IllegalArgumentException(e);
58	        }
59	
60	        setupTimeouts(builder, 30, SECONDS);
61	        builder.addNetworkInterceptor(
62	                new HttpLoggingInterceptor(System.err::println)
63	                        .setLevel(networkLogging));
64	
65	        this.httpClient = builder.build();
66	    }
67	
68	    public ClientSession getSession()
69	    {
70	        return session.get();
71	    }
72	
73	    public void setSession(ClientSession session)
74	    {
75	        this.session.set(requireNonNull(session, "session is null"));
76	    }
77	
78	    public boolean isDebug()
79	    {
80	        return debug;
81	    }
82	
83	    public Query startQuery(String query)
84	    {
85	        return new Query(startInternalQuery(session.get(), query), debug);
86	    }
87	
88	    public StatementClient startInternalQuery(String query)
89	    {
90	        return startInternalQuery(stripTransactionId(session.get()), query);
91	    }
92	
93	    private StatementClient startInternalQuery(ClientSession session, String query)
94	    {
95	        OkHttpClient.Builder builder = httpClient.newBuilder();
96	        sslSetup.accept(builder);
97	        OkHttpClient client = builder.build();
98	
99	        return newStatementClient((Call.Factory) client, session, query);
100	    }
101	
102	    @Override
103	    public void close()
104	    {
105	        httpClient.dispatcher().executorService().shutdown();
106	        httpClient.connectionPool().evictAll();
107	    }
108	}
