27	 * Parses and extracts parameters from a Trino JDBC URL.
28	 */
29	public final class TrinoDriverUri
30	        extends TrinoUri
31	{
32	    private static final String JDBC_URL_PREFIX = "jdbc:";
33	    private static final String JDBC_URL_START = JDBC_URL_PREFIX + "trino:";
34	
35	    private TrinoDriverUri(String uri, Properties driverProperties)
36	            throws SQLException
37	    {
38	        super(parseDriverUrl(uri), driverProperties);
39	    }
40	
41	    public static TrinoDriverUri create(String url, Properties properties)
42	            throws SQLException
43	    {
44	        return new TrinoDriverUri(url, firstNonNull(properties, new Properties()));
45	    }
46	
47	    public static boolean acceptsURL(String url)
48	    {
49	        return url.startsWith(JDBC_URL_START);
50	    }
51	
52	    private static URI parseDriverUrl(String url)
53	            throws SQLException
54	    {
55	        validatePrefix(url);
56	        URI uri = parseUrl(url);
57	
58	        if (isNullOrEmpty(uri.getHost())) {
59	            throw new SQLException("No host specified: " + url);
60	        }
61	        if (uri.getPort() == -1) {
62	            throw new SQLException("No port number specified: " + url);
63	        }
64	        if ((uri.getPort() < 1) || (uri.getPort() > 65535)) {
65	            throw new SQLException("Invalid port number: " + url);
66	        }
67	        return uri;
68	    }
69	
70	    private static URI parseUrl(String url)
71	            throws SQLException
72	    {
73	        try {
74	            return new URI(url.substring(JDBC_URL_PREFIX.length()));
75	        }
76	        catch (URISyntaxException e) {
77	            throw new SQLException("Invalid JDBC URL: " + url, e);
78	        }
79	    }
80	
81	    private static void validatePrefix(String url)
82	            throws SQLException
83	    {
84	        if (!url.startsWith(JDBC_URL_START)) {
85	            throw new SQLException("Invalid JDBC URL: " + url);
86	        }
87	
88	        if (url.equals(JDBC_URL_START)) {
89	            throw new SQLException("Empty JDBC URL: " + url);
90	        }
91	    }
92	}
