+            case "debug":
+            case "historyFile":
+            case "progress":
+            case "execute":
+            case "outputFormat":
+            case "outputFormatInteractive":
+            case "pager":
+            case "ignoreErrors":
+            case "editingMode":
+            case "disableAutoSuggestion":
+                return true;
+        }
