+{
+    private MockWebServer server;
+
+    @BeforeEach
+    public void setup()
+            throws Exception
+    {
+        server = new MockWebServer();
+        SSLContext sslContext = buildTestSslContext();
+        server.useHttps(sslContext.getSocketFactory(), false);
+        server.start();
+    }
+
+    @AfterEach
